import { Injectable } from '@nestjs/common';
import { MailService } from '../mail/mail.service';

export interface Recipient {
  id: string;
  email: string;
}

@Injectable()
export class NotificationService {
  constructor(private readonly mailService: MailService) {}

  async sendAnnouncement(recipients: Recipient[], subject: string, body: string): Promise<void> {
    // BUG (bulk path): sequential awaited sends in one request.
    // No concurrency, no rate limit vs relay quota, no retry, no per-recipient
    // progress checkpoint -> a crash at recipient N loses progress 0..N-1,
    // and a slow relay makes this whole endpoint time out.
    for (const recipient of recipients) {
      await this.mailService.sendMail(recipient.email, subject, body);
    }
  }
}
